import datetime

def parse_date(val):
    val = val.strip()
    if not val:
        return None
    if val.isdigit():
        serial = int(val)
        # Excel leap year bug: 1900-02-29 is serial 60
        if serial == 60:
            return "1900-02-29"
        elif serial < 60:
            base = datetime.date(1899, 12, 31)
        else:
            base = datetime.date(1899, 12, 30)
        return (base + datetime.timedelta(days=serial)).strftime("%Y-%m-%d")
    return val

def parse_amount(val):
    val = val.strip()
    if not val:
        return None
    val = val.replace(',', '').replace('$', '')
    try:
        float(val)
        return val
    except ValueError:
        return val

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    lca_path = os.path.join(packet_dir, 'lca_disclosure.csv')

