        else:
            d = datetime.date(1899, 12, 31) + datetime.timedelta(days=excel_date)
        return d.strftime("%Y-%m-%d")
    except ValueError:
        for fmt in ("%m/%d/%Y", "%Y-%m-%d", "%d/%m/%Y", "%m-%d-%Y", "%B %d, %Y", "%b %d, %Y"):
            try:
                d = datetime.datetime.strptime(date_str, fmt).date()
                return d.strftime("%Y-%m-%d")
            except ValueError:
                pass
        return date_str

