import csv
import json
import sys
import os
import datetime

def parse_date(val):
    val = val.strip()
    if not val:
        return "ABSENT"
    if val.isdigit():
        excel_date = int(val)
        # Excel's epoch starts at 1900-01-01, but it incorrectly considers 1900 a leap year.
        # For dates after 1900-02-28, the effective epoch is 1899-12-30.
        dt = datetime.date(1899, 12, 30) + datetime.timedelta(days=excel_date)
        return dt.strftime("%Y-%m-%d")

    # Fallback for standard date formats if not in Excel serial format
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m/%d/%y", "%d-%b-%y", "%d-%b-%Y", "%Y/%m/%d"):
        try:
            return datetime.datetime.strptime(val, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass
    return val

def parse_amount(val):
    val = val.strip()
    if not val:
        return "ABSENT"
    val = val.replace(',', '').replace('$', '')
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    lca_path = os.path.join(packet_dir, 'lca_disclosure.csv')

    records = {}
    if os.path.exists(lca_path):
        with open(lca_path, 'r', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            for row in reader:
                case_no = row.get('CASE_NUMBER', '').strip()
                if not case_no:
                    continue
                if case_no not in records:
                    records[case_no] = []
                records[case_no].append(row)

    results = {}
    for pair in manifest.get('pairs', []):
        try:
            rule_id, entity = pair.split('::')
        except ValueError:
            continue

        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            values = set()
            doc_name = "lca_disclosure"

            if entity in records:
                for row in records[entity]:
                    val = "ABSENT"
                    if rule_id == "lca.wage_105":
                        if fact == "offered wage":
                            val = parse_amount(row.get('WAGE_RATE_OF_PAY_FROM', ''))
                        elif fact == "prevailing wage":
                            val = parse_amount(row.get('PREVAILING_WAGE', ''))
                    elif rule_id == "lca.three_years":
                        if fact == "begin date":
                            val = parse_date(row.get('BEGIN_DATE', ''))
                        elif fact == "end date":
                            val = parse_date(row.get('END_DATE', ''))

                    if val != "ABSENT":
                        values.add(val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()

